// ── Interface earns its place: state, identity, several operations ──
abstract interface class RetryPolicy {
  String get name;                       // identity for logs and metrics
  bool shouldRetry(Object error, int attempt);
  Duration delayFor(int attempt);
}

class ExponentialBackoff implements RetryPolicy {
  ExponentialBackoff({this.maxAttempts = 4, this.base = const Duration(seconds: 1)});

  final int maxAttempts;
  final Duration base;

  @override
  String get name => 'exponential';

  @override
  bool shouldRetry(Object error, int attempt) =>
      attempt < maxAttempts && error is! AuthException;

  @override
  Duration delayFor(int attempt) => base * (1 << attempt);
}

