typedef Handler<Req, Res> = Future<Res> Function(Req request);
typedef Middleware<Req, Res> = Handler<Req, Res> Function(Handler<Req, Res> next);

Handler<Req, Res> pipeline<Req, Res>(
  List<Middleware<Req, Res>> stages,
  Handler<Req, Res> terminal,
) =>
    stages.reversed.fold(terminal, (next, stage) => stage(next));

// ── Stages ──
Middleware<ApiRequest, ApiResponse> logging(Logger log) => (next) => (req) async {
      final started = DateTime.now();
      final res = await next(req);
      log.debug('${req.method} ${req.path} -> ${res.status} '
          'in ${DateTime.now().difference(started).inMilliseconds}ms');
      return res;
    };

Middleware<ApiRequest, ApiResponse> auth(TokenStore tokens) => (next) => (req) async {
      final token = await tokens.access();
      return next(req.withHeader('Authorization', 'Bearer $token'));
    };

Middleware<ApiRequest, ApiResponse> cache(ResponseCache store) => (next) => (req) async {
      if (req.method != 'GET') return next(req);
      final hit = store.get(req.path);
      if (hit != null) return hit;                 // short-circuits the rest
      final res = await next(req);
      store.put(req.path, res);
      return res;
    };

// ── Order is data, and it is visible in one place ──
final send = pipeline<ApiRequest, ApiResponse>(
  [
    logging(log),
    if (kDebugMode) chaos(failureRate: 0.1),
    auth(tokens),
    cache(responseCache),
  ],
  transport.send,
);

// ── First-match-wins variant, for deep links ──
abstract interface class LinkHandler {
  bool canHandle(Uri uri);
  Future<void> handle(Uri uri);
}

Future<void> dispatch(Uri uri, List<LinkHandler> handlers) async {
  for (final h in handlers) {
    if (h.canHandle(uri)) return h.handle(uri);
  }
  return handlers.last.handle(uri);              // fallback: open home
}

// Testing one stage in isolation
test('cache short-circuits the chain', () async {
  var tailCalls = 0;
  final handler = cache(store)((_) async {
    tailCalls++;
    return ApiResponse.ok();
  });
  await handler(ApiRequest.get('/feed'));
  await handler(ApiRequest.get('/feed'));
  expect(tailCalls, 1);
});
